import { z } from 'zod';
import { Button, Group, NumberInput, SimpleGrid, Stack, Text, TextInput } from '@mantine/core';
import { schemaResolver, useForm } from '@mantine/form';
import { randomId } from '@mantine/hooks';
import { notifications } from '@mantine/notifications';
import { Ticket, TicketsList } from './TicketsList';

interface RegistrationValues {
  name: string;
  email: string;
  age: number | '';
  address: {
    city: string;
    zip: string;
  };
  tickets: Ticket[];
}

const schema = z.object({
  name: z.string().min(2, { error: 'Name must have at least 2 letters' }),
  email: z.email({ error: 'Invalid email' }),
  age: z.number({ error: 'Age is required' }).min(18, { error: 'You must be at least 18' }),
  address: z.object({
    city: z.string().min(1, { error: 'City is required' }),
    zip: z.string().regex(/^\d{5}$/, { error: 'Zip code must be 5 digits' }),
  }),
  tickets: z
    .array(
      z.object({
        holder: z.string().min(2, { error: 'Holder name must have at least 2 letters' }),
      })
    )
    .min(1, { error: 'Add at least one ticket' }),
});

export function ZodSchema() {
  const form = useForm<RegistrationValues>({
    mode: 'uncontrolled',
    initialValues: {
      name: '',
      email: '',
      age: '',
      address: { city: '', zip: '' },
      tickets: [{ key: randomId(), holder: '' }],
    },
    validate: schemaResolver(schema, { sync: true }),
  });

  const handleSubmit = (values: RegistrationValues) => {
    notifications.show({
      title: 'Registration complete',
      message: `${values.tickets.length} ${values.tickets.length === 1 ? 'ticket' : 'tickets'} reserved for ${values.name}, confirmation sent to ${values.email}`,
    });
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit)}>
      <Stack>
        <TextInput
          label="Name"
          placeholder="John Doe"
          withAsterisk
          {...form.getInputProps('name')}
        />
        <TextInput
          label="Email"
          placeholder="john@mantine.dev"
          withAsterisk
          {...form.getInputProps('email')}
        />
        <NumberInput
          label="Age"
          placeholder="18"
          withAsterisk
          min={0}
          max={120}
          {...form.getInputProps('age')}
        />
        <SimpleGrid cols={{ base: 1, sm: 2 }}>
          <TextInput
            label="City"
            placeholder="Berlin"
            withAsterisk
            {...form.getInputProps('address.city')}
          />
          <TextInput
            label="Zip code"
            placeholder="10115"
            withAsterisk
            {...form.getInputProps('address.zip')}
          />
        </SimpleGrid>
        <div>
          <Text size="sm" fw={500} mb="xs">
            Tickets
          </Text>
          <TicketsList form={form} />
        </div>
        <Group justify="flex-end">
          <Button type="submit">Register</Button>
        </Group>
      </Stack>
    </form>
  );
}

import { PlusIcon, TrashIcon } from '@phosphor-icons/react';
import { ActionIcon, Button, Group, Stack, Text, TextInput } from '@mantine/core';
import { UseFormReturnType } from '@mantine/form';
import { randomId } from '@mantine/hooks';

export interface Ticket {
  key: string;
  holder: string;
}

interface TicketsListProps {
  form: UseFormReturnType<{ tickets: Ticket[] }>;
}

export function TicketsList({ form }: TicketsListProps) {
  const tickets = form.getValues().tickets.map((ticket, index) => (
    <Group key={ticket.key} align="flex-start" wrap="nowrap">
      <TextInput
        placeholder="Ticket holder name"
        aria-label="Ticket holder name"
        style={{ flex: 1 }}
        {...form.getInputProps(`tickets.${index}.holder`)}
      />
      <ActionIcon
        variant="default"
        size="input-sm"
        aria-label="Remove ticket"
        onClick={() => form.removeListItem('tickets', index)}
      >
        <TrashIcon size={18} color="var(--mantine-color-red-6)" />
      </ActionIcon>
    </Group>
  ));

  return (
    <Stack gap="xs">
      {tickets.length > 0 ? (
        tickets
      ) : (
        <Text size="sm" c="dimmed">
          No tickets yet
        </Text>
      )}
      {form.errors.tickets && (
        <Text c="red" size="sm">
          {form.errors.tickets}
        </Text>
      )}
      <Group>
        <Button
          variant="default"
          leftSection={<PlusIcon size={16} />}
          onClick={() => form.insertListItem('tickets', { key: randomId(), holder: '' })}
        >
          Add ticket
        </Button>
      </Group>
    </Stack>
  );
}
